from typing import Callable, Optional, Sequence, TypeVar
T = TypeVar("T")

def find_fixed_point(f: Callable[[T], T], states: Sequence[T]) -> Optional[T]:
    """Return a world-state reproduced by one loop traversal, or None if paradoxical."""
    for s in states:
        if f(s) == s:
            return s
    return None

def is_paradoxical(f: Callable[[T], T], states: Sequence[T]) -> bool:
    return all(f(s) != s for s in states)

if __name__ == "__main__":
    flip: Callable[[bool], bool] = lambda s: not s   # grandfather: flip ancestor's fate
    states = [True, False]
    print("paradoxical (no fixed point)?", is_paradoxical(flip, states))
    print("fixed point:", find_fixed_point(flip, states))
    print("=> grandfather paradox admits NO self-consistent single-timeline history")

